decorators:
@Module({
  imports: [
    TypeOrmModule.forRoot(options),
    TypeOrmModule.forRoot({ type: "sqlite", database: "second.sqlite", entities: [Thing] }, "second"),
  ],
})

@Module({
  imports: [TypeOrmModule.forRoot({ type: "mysql", database: "a", autoLoadEntities: true }), AlphaModule],
})

@Module({
  imports: [TypeOrmModule.forRoot({ type: "mysql", database: "b", autoLoadEntities: true }), BetaModule],
})

@Module({
  imports: [TypeOrmModule.forRoot({ name: "lazy", type: "mysql", database: "c", autoLoadEntities: true })],
})

@Module({
  imports: [
    TypeOrmModule.forRootAsync({
      inject: [ConfigService],
      useFactory: (config: ConfigService) => {
        let logging = process.env.DB_LOGGING;
        try {
          logging = JSON.parse(logging ?? "false");
        } catch {
          // ignore
        }
        return { ...config.get("database"), autoLoadEntities: true, logging };
      },
      dataSourceFactory: async (options) => {
        const dataSource = await new DataSource(options).initialize();
        return dataSource;
      },
    }),
    UserModule,
  ],
})
